import { describe, it, expect } from "vitest";
import { CATALOG_KEYS } from "../../../src/utils/catalog/lensCatalog.js";
import { CATALOG_ENTRIES } from "../../../src/pages/lensIndex/catalog.js";
import buildMeta from "../../../src/generated/build-metadata.json";

/**
 * These tests verify that the build-time metadata (generated by
 * generate-build-metadata.mjs) stays in sync with the runtime code.
 * They require `npm run generate:metadata` to have been run first.
 */
describe("build-route-sync", () => {
  it("every lens key has freshness metadata", () => {
    const freshness = buildMeta.lensFreshness as Record<
      string,
      { publishedOn: string; publishedAt: string; lastModified: string; publicationOrder: number }
    >;

    for (const key of buildMeta.lensKeys) {
      expect(freshness[key]).toBeDefined();
      expect(freshness[key].publishedOn).toMatch(/^\d{4}-\d{2}-\d{2}$/);
      expect(freshness[key].publishedAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
      expect(freshness[key].lastModified).toMatch(/^\d{4}-\d{2}-\d{2}$/);
      expect(Number.isInteger(freshness[key].publicationOrder)).toBe(true);
    }
    expect(
      Object.values(freshness)
        .map((entry) => entry.publicationOrder)
        .sort((a, b) => a - b),
    ).toEqual(Array.from({ length: buildMeta.lensKeys.length }, (_, index) => index));
  });

  it("maker slugs are exactly the makers represented by visible lens pages", () => {
    const expectedMakerSlugs = [
      ...new Set(
        CATALOG_ENTRIES.flatMap((entry) => entry.makerAssociations.map((association) => association.maker.slug)),
      ),
    ].sort();

    expect(buildMeta.makerSlugs).toEqual(expectedMakerSlugs);
  });

  it("routes array is non-empty and includes expected static routes", () => {
    const routes = buildMeta.routes;

    expect(routes.length).toBeGreaterThan(0);
    expect(routes).toContain("/");
    expect(routes).toContain("/search");
    expect(routes).toContain("/lenses");
    expect(routes).toContain("/makers");
    expect(routes).toContain("/mounts");
    expect(routes).toContain("/formats");
    expect(routes).toContain("/authors");
    expect(routes).toContain("/patents");
    expect(routes).toContain("/articles");
  });

  it("lensKeys array matches routes with /lens/ prefix", () => {
    const lensKeys = buildMeta.lensKeys;
    const lensRoutes = buildMeta.routes.filter((r: string) => r.startsWith("/lens/"));

    expect(lensKeys).toEqual([...CATALOG_KEYS].sort());
    expect(lensRoutes.length).toBe(lensKeys.length);
    for (const key of lensKeys) {
      expect(lensRoutes).toContain(`/lens/${key}`);
    }
  });

  it("article slugs match routes with /articles/ prefix", () => {
    const articleSlugs = buildMeta.articles.map((a: { slug: string }) => a.slug);
    const articleRoutes = buildMeta.routes.filter((r: string) => r.startsWith("/articles/"));

    expect(articleRoutes.length).toBe(articleSlugs.length);
    for (const slug of articleSlugs) {
      expect(articleRoutes).toContain(`/articles/${slug}`);
    }
  });

  it("articles include timestamped publication metadata in generated order", () => {
    for (const [index, article] of (
      buildMeta.articles as {
        publishedOn: string;
        publishedAt: string;
        lastModified: string;
        publicationOrder: number;
      }[]
    ).entries()) {
      expect(article.publishedOn).toMatch(/^\d{4}-\d{2}-\d{2}$/);
      expect(article.publishedAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
      expect(article.lastModified).toMatch(/^\d{4}-\d{2}-\d{2}$/);
      expect(article.publicationOrder).toBe(index);
    }
  });

  it("published dates retain historical ordering instead of collapsing to one build date", () => {
    const lensFreshness = Object.values(
      buildMeta.lensFreshness as Record<string, { publishedOn: string; lastModified: string }>,
    );
    const lensPublishedDates = new Set(lensFreshness.map((entry) => entry.publishedOn));
    const articlePublishedDates = new Set(
      (buildMeta.articles as { publishedOn: string; lastModified: string }[]).map((article) => article.publishedOn),
    );

    expect(lensPublishedDates.size).toBeGreaterThan(1);
    expect(articlePublishedDates.size).toBeGreaterThan(1);
  });

  it("makerSlugs match routes with /makers/ prefix", () => {
    const makerRoutes = buildMeta.routes.filter((r: string) => r.startsWith("/makers/"));

    expect(makerRoutes.length).toBe(buildMeta.makerSlugs.length);
    for (const slug of buildMeta.makerSlugs) {
      expect(makerRoutes).toContain(`/makers/${slug}`);
    }
  });

  it("generated authors match the prerendered author routes", () => {
    /* Slug uniqueness and non-empty lensKeys/patentCount live with the runtime
       AUTHORS checks (authorCatalog.test.ts, partyPatentParity.test.ts), which
       read the same generated entries. Only route correspondence is unique here. */
    const authorRoutes = buildMeta.routes.filter((route: string) => route.startsWith("/authors/"));

    expect(authorRoutes.length).toBe(buildMeta.authors.length);
    for (const author of buildMeta.authors) {
      expect(authorRoutes).toContain(`/authors/${author.slug}`);
      expect(author.name).toBeTruthy();
    }
  });

  it("mountIds and formatIds match cluster routes", () => {
    const expectedMountIds = [
      ...new Set(CATALOG_ENTRIES.flatMap((entry) => entry.lensMounts.map((mount) => mount.id))),
    ].sort();
    const expectedFormatIds = [
      ...new Set(CATALOG_ENTRIES.flatMap((entry) => (entry.imageFormat ? [entry.imageFormat.id] : []))),
    ].sort();
    const mountRoutes = buildMeta.routes.filter((r: string) => r.startsWith("/mounts/"));
    const formatRoutes = buildMeta.routes.filter((r: string) => r.startsWith("/formats/"));

    expect(buildMeta.mountIds).toEqual(expectedMountIds);
    expect(buildMeta.formatIds).toEqual(expectedFormatIds);
    expect(mountRoutes.length).toBe(expectedMountIds.length);
    expect(formatRoutes.length).toBe(expectedFormatIds.length);
    for (const id of expectedMountIds) {
      expect(mountRoutes).toContain(`/mounts/${id}`);
    }
    for (const id of expectedFormatIds) {
      expect(formatRoutes).toContain(`/formats/${id}`);
    }
  });

  it("every prerendered route has freshness metadata", () => {
    const routeFreshness = buildMeta.routeFreshness as Record<string, { publishedOn: string; lastModified: string }>;

    for (const route of buildMeta.routes as string[]) {
      expect(routeFreshness[route]).toBeDefined();
      expect(routeFreshness[route].publishedOn).toMatch(/^\d{4}-\d{2}-\d{2}$/);
      expect(routeFreshness[route].lastModified).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    }
  });
});
